// Emits the smallest milestone crossed and not yet notified (90/60/30, or 0 = overdue)
const BASE = 'REPLACE_WITH_N8N_BASE_URL'; // e.g. https://n8n.example.com
const today = new Date(); today.setHours(0, 0, 0, 0);
const out = [];
for (const { json: c } of $input.all()) {
  if (c.status !== 'Active' || c.decision || !c.decision_deadline) continue;
  const days = Math.round((new Date(c.decision_deadline) - today) / 86400000);
  const sent = c.last_milestone_sent === '' || c.last_milestone_sent === undefined ? 9999 : Number(c.last_milestone_sent);
  let m = null;
  if (days < 0) { if (sent > 0) m = 0; }
  else for (const x of [90, 60, 30]) if (days <= x && sent > x) m = x;
  if (m === null) continue;
  const link = d => `${BASE}/webhook/contract-decision?id=${encodeURIComponent(c.contract_id)}&t=${c.approval_token}&d=${d}`;
  const urgency = m === 0 ? ':rotating_light: OVERDUE' : m === 30 ? ':red_circle: 30-day' : m === 60 ? ':large_orange_circle: 60-day' : ':large_yellow_circle: 90-day';
  const autoTxt = c.auto_renew === 'Yes' ? 'Auto-renews if no notice is served.' : 'Expires unless renewed.';
  const blocks = [
    { type: 'header', text: { type: 'plain_text', text: `Contract renewal decision – ${m === 0 ? 'overdue' : m + ' days'}` } },
    { type: 'section', text: { type: 'mrkdwn', text:
      `${urgency} *<${c.file_link}|${c.contract_title}>*\n*Counterparty:* ${c.counterparty || '–'}\n*Expiry:* ${c.expiry_date}  |  *Notice:* ${c.notice_period_days} days\n*Decision deadline:* ${c.decision_deadline} (${days} days left)\n${autoTxt}\n*Value:* ${c.contract_value || '–'} ${c.currency || ''}` } },
    { type: 'actions', elements: [
      { type: 'button', style: 'primary', text: { type: 'plain_text', text: '✅ Renew' }, url: link('renew') },
      { type: 'button', style: 'danger', text: { type: 'plain_text', text: '🛑 Terminate' }, url: link('terminate') },
      { type: 'button', text: { type: 'plain_text', text: '📄 Open contract' }, url: c.file_link }
    ] }
  ];
  out.push({ json: { contract_id: c.contract_id, milestone: m, days_left: days, contract_title: c.contract_title, slack_blocks: blocks } });
}
return out;

