const ai = $json.message?.content || {};
const file = $('New Contract in Drive').item.json;
const toDate = s => { if (!s) return null; const d = new Date(s); return isNaN(d) ? null : d; };
const iso = d => d ? d.toISOString().slice(0, 10) : '';
const expiry = toDate(ai.expiry_date);
const notice = Number(ai.notice_period_days) || 0;
let deadline = null;
if (expiry) { deadline = new Date(expiry); deadline.setDate(deadline.getDate() - notice); }
const daysLeft = deadline ? Math.ceil((deadline - new Date()) / 86400000) : null;
const token = Array.from({ length: 32 }, () => Math.floor(Math.random() * 16).toString(16)).join('');
const status = !expiry ? 'Review Needed' : 'Active';
return { json: {
  contract_id: file.id, file_name: file.name,
  file_link: file.webViewLink || `https://drive.google.com/file/d/${file.id}/view`,
  contract_title: ai.contract_title || file.name, counterparty: ai.counterparty_name || '',
  counterparty_email: ai.counterparty_email || '', effective_date: ai.effective_date || '',
  expiry_date: iso(expiry), auto_renew: ai.auto_renew === true ? 'Yes' : 'No',
  auto_renew_clause: ai.auto_renew_clause || '', renewal_term_months: ai.renewal_term_months ?? '',
  notice_period_days: notice, decision_deadline: iso(deadline), days_to_deadline: daysLeft ?? '',
  contract_value: ai.contract_value ?? '', currency: ai.currency || '',
  termination_clause: ai.termination_clause || '', summary: ai.summary || '',
  risks: (ai.key_risks || []).join(' | '), status, last_milestone_sent: '', decision: '',
  decision_at: '', approval_token: token, registered_at: new Date().toISOString(),
  obligations: Array.isArray(ai.obligations) ? ai.obligations : []
}};

