const out = [];
for (const { json: c } of $('Build Contract Record').all()) {
  (c.obligations || []).forEach((o, i) => out.push({ json: {
    obligation_id: `${c.contract_id}_${i + 1}`, contract_id: c.contract_id,
    contract_title: c.contract_title, counterparty: c.counterparty,
    obligation: o.obligation || '', owner_party: o.owner_party || '',
    due_date: o.due_date || '', frequency: o.frequency || 'one-time', status: 'Open'
  }}));
}
return out;

const today = new Date(); today.setHours(0, 0, 0, 0);
const rows = $input.all().map(i => i.json).filter(o => o.due_date && !/^(done|closed|completed)$/i.test(String(o.status || '').trim()))
  .map(o => ({ ...o, days: Math.round((new Date(o.due_date) - today) / 86400000) }))
  .filter(o => o.days <= 7).sort((a, b) => a.days - b.days);
if (!rows.length) return [];
const line = o => `${o.days < 0 ? ':red_circle: OVERDUE ' + (-o.days) + 'd' : o.days === 0 ? ':large_orange_circle: TODAY' : ':calendar: in ' + o.days + 'd'} · *${o.contract_title}* (${o.owner_party}): ${o.obligation} (${o.due_date})`;
return [{ json: { text: `:clipboard: *Contract obligations due within 7 days (${rows.length})*\n` + rows.slice(0, 30).map(line).join('\n') } }];

const q = $('Decision Link Clicked').first().json.query || {};
const c = $input.first()?.json || {};
const decision = String(q.d || '').toLowerCase();
let reason = '';
if (!c.contract_id) reason = 'Contract not found';
else if (!c.approval_token || q.t !== c.approval_token) reason = 'Invalid or expired link';
else if (c.decision) reason = `A decision is already recorded: ${c.decision}`;
else if (!['renew', 'terminate'].includes(decision)) reason = 'Unknown decision';
return [{ json: { ...c, decision_requested: decision, valid: !reason, reason } }];

